<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><span class="eyebrow">TRAZABILIDAD</span><h1>Auditoría</h1><p>Consulta quién hizo cada cambio y cuándo ocurrió.</p></div><span class="tag">Solo consulta</span></div><section class="panel"><form class="filter-bar" method="get"><div class="search-field"><label class="visually-hidden" for="q">Buscar eventos</label><input class="form-control" id="q" name="q" placeholder="Operación o identificador del objeto…" value="<?= V::escape($filters['q']) ?>"></div><button class="btn btn-outline-secondary">Filtrar</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Evento</th><th>Administrador</th><th>Fecha</th><th>Detalle</th></tr></thead><tbody><?php foreach ($listing['rows'] as $event): $payload=json_decode($event['payload_json'],true); ?><tr><td><strong><?= V::escape(V::action($event['operation'])) ?></strong><small class="cell-sub">#<?= (int)$event['sequence'] ?></small></td><td><?= V::escape($event['actor_name']??'Sistema / acceso anónimo') ?></td><td><?= V::escape(V::date($event['occurred_at'])) ?></td><td><details><summary>Consultar</summary><dl class="audit-detail"><dt>Objeto</dt><dd><?= V::escape($event['target_type']) ?></dd><dt>Identificador</dt><dd class="mono"><?= V::escape($event['target_id']??'—') ?></dd><dt>Motivo</dt><dd><?= V::escape($payload['reason']?:'—') ?></dd><dt>Registro</dt><dd class="mono"><?= V::escape(json_encode($payload['metadata'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></dd></dl></details></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/pagination.php'; ?></section>
